    /// <summary>品牌是填充路径；不能套用 Lucide 的轮廓描边。</summary>
    internal static bool TryGet(string kind, out Geometry? geometry) => Paths.TryGetValue(kind, out geometry);

    private static Geometry Freeze(string path)
    {
        var geometry = Geometry.Parse(path);
        geometry.Freeze();
        return geometry;
    }
